head.script:
            // 파라미터 임시 저장소
            // 중복 체크 여부

// scwin.onpageload, scwin.onpageunload 함수
            scwin.onpageload = function() {

                scwin.vScrenID = "ULDTMS03120.xml";
// 전역 변수 선언
scwin.storageId = "";
scwin.dupleYn = "Y";
                scwin.storageId = $c.data.getParameter("storageId");

                // 상장고시 시장구분코드, 서식관리 기관 구분코드, 보고서 본문 구분코드, 조회공시구분코드, 조회공시 내용 구분코드, 
                // 조회공시 답변 구분코드, 서식작성방식 구분코드, 서식별 사용자 구분코드
                const list = ["LD_MKT_TP_CD", "FORM_ADM_INST_TP_CD", "WRTRPT_MAINDOC_TP_CD", "INQDISCLS_TP_CD", 
                              "INQDISCLS_CONTN_TP_CD", "INQDISCLS_ANS_TP_CD", "FORM_WRT_METHD_TP_CD", "BYFORM_USR_TP_CD"];
                const params = {"cdEngNmList":list};

                // 서식분류 정보 조회
                const sbmOptions = {
                    id : "sbm_upclss",
                    action : "/api/code/form-upclss",
                    method : "get",
                    submitDoneHandler : scwin.sbm_upclss_submitdone,
                    processMsg : "공통코드 조회중..."
                };
                $c.sbm.executeDynamic(sbmOptions);                
                // 코드 정보 조회
                $c.sbm.execute(sbm_code, params);
                // 기존 서식 hide
                grp_form2.setStyle("display", "none");
            };

// WebSquare 컴포넌트 이벤트 함수
            scwin.rdo_form_onchange = function (info) {

                // 초기화 
                scwin.clear();              

                if (info.newValue === "0") {
                    grp_form1.setStyle("display", "flex");
                    grp_form2.setStyle("display", "none");

                    ibx_oldFormCd.setValue("");                    
                    tbx_formVer.setValue("");                    
                } else {
                    grp_form1.setStyle("display", "none");
                    grp_form2.setStyle("display", "flex");

                    ibx_formCd.setValue("");
                    scwin.dupleYn = "N";
                }
            };

            scwin.btn_search_onclick = async function (e) {

                const url_ = "/ui/TMS/ULDTMS03011.xml";
                const options = {
                    id: "ULDTMS03011_POP",
                    popupName: "서식조회",
                    width: "1000",
                    height: "650",
                    frameModal: "top"
                };

                const result = await $c.win.openPopup(url_, options, {});
                if (!$c.util.isEmpty(result)) {
                    // 결과 값이 있을 경우 상세 조회
                    ibx_oldFormCd.setValue(result.formCd + " - " + result.formKorNm);
                    tbx_formVer.setValue("기존 서식 버전 (v" + result.formVer + ")");                    

                    const params = {};
                    params.formCd = result.formCd;
                    params.formVer = result.formVer;

                    $c.sbm.execute(sbm_detail, params);	                                        
                }
            };

// 저장
            scwin.btn_insert_onclick = function (e) {

                // validation 체크
                if (!$c.tms.validateGroupTms("grp_input")) return;
                // 서식 양식 정보 체크
                /*                
                if ($c.util.isEmpty(ibx_roleId.getValue())) {
                    $c.win.alert("서식양식정보를 선택 해주세요.", function () {
                        ibx_roleId.focus();
                    });
                    return;
                } 
                */               

                // 영문명 없으며 "N/A"로 변경 처리
                if ($c.util.isEmpty(dma_save.get("formEngNm"))) {
                    dma_save.set("formEngNm", "N/A");
                }

                if (dma_save.get("wrtrptMaindocTpCd") !== "1") {
                    dma_save.set("formUpclssCd", "");
                    dma_save.set("rsnClssCd", "");                    
                }

                const formUpclssCd = dma_save.get("formUpclssCd");
                const rsnClssCd = dma_save.get("rsnClssCd");

                if ((formUpclssCd === "01" && rsnClssCd === "040") ||
                    (formUpclssCd === "01" && rsnClssCd === "041") ||
                    (formUpclssCd === "09" && rsnClssCd === "006") ||
                    (formUpclssCd === "09" && rsnClssCd === "009")) {
                    if (dma_save.get("inqdisclsTpCd") !== "A") {
                        dma_save.set("inqdisclsAnsTpCd", "");
                    }
                } else {
                    dma_save.set("inqdisclsTpCd", "");
                    dma_save.set("inqdisclsContnTpCd", "");
                    dma_save.set("inqdisclsAnsTpCd", "");
                }
                dma_save.set("roleId", ibx_roleId.getValue());                
                dma_save.set("mode", "I");

                // 서버에 전송 할 파라미터 정리(모든 값은 기본적으로 생성 서버백단에서 파싱에러 발생)
                const params = {};
                // 기본정보
                params.masterInfo = dma_save.getJSON();

                // 서식양식 정보                
                const params_sub_ = {};
                params_sub_.formCd = dma_save.get("formCd");
                params_sub_.formVer = dma_save.get("formVer");
                params_sub_.formWrtCautnContn = txa_formWrtCautnContn.getValue();

                params.wrtCautnInfo = params_sub_;

                // 서식 처리 절차
                if (dlt_list2.getRowCount() > 0) {
                    const list = [];
                    for (let i=0; i < dlt_list2.getRowCount(); i++) {
                        list.push(dlt_list2.getCellData(i, "formProcsCd"));
                    }
                    const sub_params = {};
                    sub_params.formCd = dma_save.get("formCd");
                    sub_params.formVer = dma_save.get("formVer");
                    sub_params.formProcsCds = list;

                    params.formProcessInfo = sub_params;
                } else {                    
                    params.formProcessInfo = null;
                }

                // 서식별 권한그룹정보
                if (dlt_list3.getRowCount() > 0) {
                    const list = [];
                    for (let i=0; i < dlt_list3.getRowCount(); i++) {
                        list.push(dlt_list3.getCellData(i, "formAuthId"));
                    }
                    const sub_params = {};
                    sub_params.formCd = dma_save.get("formCd");
                    sub_params.formVer = dma_save.get("formVer");
                    sub_params.formAuthCds = list;

                    params.formAuthInfo = sub_params;
                } else {                   
                    params.formAuthInfo = null;
                }

                // 공시 승인부서 정보
                if (dlt_list4.getRowCount() > 0) {
                    const list = [];
                    for (let i=0; i < dlt_list4.getRowCount(); i++) {
                        list.push(dlt_list4.getCellData(i, "apprDeptCd"));
                    }
                    const sub_params = {};
                    sub_params.formCd = dma_save.get("formCd");
                    sub_params.formVer = dma_save.get("formVer");
                    sub_params.byFormDepCds = list;

                    params.formApprInfo = sub_params;
                } else {                   
                    params.formApprInfo = null;
                }

                // 첨부문서 정보
                if (dlt_list5.getRowCount() > 0) {
                    const list1 = [];
                    const list2 = [];
                    for (let i=0; i < dlt_list5.getRowCount(); i++) {
                        list1.push(dlt_list5.getCellData(i, "formCd"));
                        list2.push("2");
                    }
                    const sub_params = {};
                    sub_params.formCd = dma_save.get("formCd");
                    sub_params.formVer = dma_save.get("formVer");
                    sub_params.wrtrptMaindocTpCd = "2";
                    sub_params.byFormDepCds = list1;
                    sub_params.formMandtryTpCds = list2;

                    params.formAttachInfo = sub_params;
                } else {                    
                    params.formAttachInfo = null;
                }

                // 단위서식
                if (dlt_list6.getRowCount() > 0) {
                    const list1 = [];
                    const list2 = [];
                    for (let i=0; i < dlt_list6.getRowCount(); i++) {
                        list1.push(dlt_list6.getCellData(i, "formCd"));
                        list2.push("3");
                    }
                    const sub_params = {};
                    sub_params.formCd = dma_save.get("formCd");
                    sub_params.formVer = dma_save.get("formVer");
                    sub_params.wrtrptMaindocTpCd = "3";
                    sub_params.byFormDepCds = list1;
                    sub_params.formMandtryTpCds = list2;

                    params.formLibraryInfo = sub_params;
                } else {                  
                    params.formLibraryInfo = null;
                }

                // 편집기 분류 정보
                if (dlt_list7.getRowCount() > 0) {
                    const list = [];
                    for (let i=0; i < dlt_list7.getRowCount(); i++) {
                        list.push(dlt_list7.getCellData(i, "editMidclssCd"));
                    }
                    const sub_params = {};
                    sub_params.formCd = dma_save.get("formCd");
                    sub_params.formVer = dma_save.get("formVer");
                    sub_params.editClssCds = list;

                    params.formEditInfo = sub_params;
                } else {                   
                    params.formEditInfo = null;
                }

                // 공시 유형분류 정보
                if (dlt_list8.getRowCount() > 0) {
                    const list1 = [];
                    const list2 = [];
                    const list3 = [];
                    for (let i=0; i < dlt_list8.getRowCount(); i++) {
                        list1.push(dlt_list8.getCellData(i, "formUpclssCd"));
                        list2.push(dlt_list8.getCellData(i, "tpClssCd"));
                        list3.push(dlt_list8.getCellData(i, "ldMktTpCd"));
                    }
                    const sub_params = {};
                    sub_params.formCd = dma_save.get("formCd");
                    sub_params.formVer = dma_save.get("formVer");                    
                    sub_params.formUpclssCds = list1;
                    sub_params.tpClssCds = list2;
                    sub_params.ldMktTpCds = list3;

                    params.formTypeClssInfo = sub_params;
                } else {                   
                    params.formTypeClssInfo = null;
                }                
                $c.sbm.execute(sbm_save, params);
            };

            scwin.btn_cancel_onclick = function (e) {

                scwin.fnMove();
            };

            scwin.ibx_formCd_onkeyup = function (e) {

                $c.tms.disableBlockKor(ibx_formCd);
                dma_save.set("formCd", ibx_formCd.getValue());
            };

            scwin.ibx_engFormCd_onkeyup = function (e) {

                $c.tms.disableBlockKor(ibx_formCd);
            };

            scwin.ibx_formVer_onkeyup = function (e) {

                // 소숫점 체크
                $c.tms.chkDecimal(ibx_formVer, 4);
            };

            scwin.ibx_engFormVer_onkeyup = function (e) {

                // 소숫점 체크
                $c.tms.chkDecimal(ibx_engFormVer, 4);
            };

            scwin.ibx_formEngNm_onkeyup = function (e) {

                $c.tms.disableBlockKor(ibx_formEngNm);
            };

            scwin.sbx_ldMktTpCd_onviewchange = function (info) {

                scwin.changeRsnTpInfo();
            };

            scwin.sbx_formUpclssCd_onviewchange = function (info) {

                scwin.changeRsnTpInfo();
            };

            scwin.sbx_inqdisclsTpCd_onviewchange = function (info) {

                scwin.chageInqdisclsInfo2();
            };

            scwin.sbx_wrtrptMaindocTpCd_onviewchange = function (info) {

                scwin.chageWrtrptMainDocInfo();
            };

            scwin.sbx_rsnClssCd_onviewchange = function (info) {

                scwin.chageInqdisclsInfo1();
            };

            scwin.sbx_engFormYn_onviewchange = function (info) {

                if (info.newValue === "Y") {
                    ibx_engFormCd.setReadOnly(false);
                    ibx_engFormVer.setReadOnly(false);
                    ibx_formEngNm.setReadOnly(false);
                } else {
                    ibx_engFormCd.setReadOnly(true);
                    ibx_engFormVer.setReadOnly(true);
                    ibx_formEngNm.setReadOnly(true);

                    ibx_engFormCd.setValue("");
                    ibx_engFormVer.setValue("");
                    ibx_formEngNm.setValue("");
                }
            };

            scwin.btn_subList_onclick = async function (e) {

                let url_ = "";                
                // 버튼에 따른 팝업 처리
                if (!$c.util.isEmpty(e)) {

                    let options = {};
                    options.width = "760";
                    options.height = "460";

                    const id_ = e.target?.id;
                    // 객체를 받아서 바로 처리
                    let listObj = null;
                    if (id_.indexOf("btn_subList2") > -1) {                        
                        options.popupName = "서식처리절차 변경";
                        options.id = "ULDTMS03050_POP";
                        url_ = "/ui/TMS/ULDTMS03050.xml";
                        listObj = dlt_list2;                        
                    } else if (id_.indexOf("btn_subList3") > -1) {                        
                        options.popupName = "서식별 권한그룹정보 변경";
                        options.id = "ULDTMS03060_POP";
                        url_ = "/ui/TMS/ULDTMS03060.xml";
                        listObj = dlt_list3;                        
                    } else if (id_.indexOf("btn_subList4") > -1) {                        
                        options.popupName = "공시승인부서정보 변경";
                        options.id = "ULDTMS03070_POP";
                        url_ = "/ui/TMS/ULDTMS03070.xml";
                        listObj = dlt_list4;                        
                    } else if (id_.indexOf("btn_subList5") > -1) {                        
                        options.popupName = "첨부문서정보 변경";
                        options.id = "ULDTMS03080_POP";
                        url_ = "/ui/TMS/ULDTMS03080.xml";
                        listObj = dlt_list5;                        
                    } else if (id_.indexOf("btn_subList6") > -1) {                        
                        options.popupName = "단위서식 변경";
                        options.id = "ULDTMS03090_POP";
                        url_ = "/ui/TMS/ULDTMS03090.xml";
                        listObj = dlt_list6;                        
                    } else if (id_.indexOf("btn_subList7") > -1) {                        
                        options.popupName = "편집기분류정보 변경";
                        options.id = "ULDTMS03100_POP";
                        url_ = "/ui/TMS/ULDTMS03100.xml";
                        listObj = dlt_list7;                        
                    } else if (id_.indexOf("btn_subList8") > -1) {                        
                        options.popupName = "공시유형분류정보 변경";
                        options.id = "ULDTMS03110_POP";                        
                        url_ = "/ui/TMS/ULDTMS03110.xml";
                        listObj = dlt_list8;
                    } else if (id_.indexOf("btn_subList9") > -1) {                        
                        options.popupName = "공시조회유형정보 변경";
                        options.id = "ULDTMS03115_POP";                        
                        url_ = "/ui/TMS/ULDTMS03115.xml";
                        listObj = dlt_list9;
                    }

                    let params = {};
                    params.formCd = dma_save.get("formCd");
                    params.formVer = dma_save.get("formVer");
                    params.directYn = "Y";

                    const result = await $c.win.openPopup(url_, options, params);                    
                    if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {                        
                        listObj.setJSON({});                        
                        listObj.setJSON(result.list);
                    }
                }
            };

// 일반 함수
            scwin.sbm_upclss_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // select box 자동 생성
                    $c.tms.setSelectData(result.body, sbx_formUpclssCd, "formUpclssNm", "formUpclssCd");                    
                } else {
                    $c.win.alert(result.message);
                }
            };

            scwin.sbm_code_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // select box 자동 생성
                    // 서식관리 기관 구분코드
                    $c.tms.setSelectData(result.body, sbx_formAdmInstTpCd, "cdValNm", "cdVal", "FORM_ADM_INST_TP_CD", "cdEngNm");
                    // 상장고시 시장구분코드                                        
                    $c.tms.setSelectData(result.body, sbx_ldMktTpCd, "cdValNm", "cdVal", "LD_MKT_TP_CD", "cdEngNm");
                    // 보고서 본문 구분코드
                    $c.tms.setSelectData(result.body, sbx_wrtrptMaindocTpCd, "cdValNm", "cdVal", "WRTRPT_MAINDOC_TP_CD", "cdEngNm");                                        
                    // 조회공시구분코드
                    $c.tms.setSelectData(result.body, sbx_inqdisclsTpCd, "cdValNm", "cdVal", "INQDISCLS_TP_CD", "cdEngNm");
                    // 조회공시 내용 구분코드
                    $c.tms.setSelectData(result.body, sbx_inqdisclsContnTpCd, "cdValNm", "cdVal", "INQDISCLS_CONTN_TP_CD", "cdEngNm");
                    // 조회공시 답변 구분코드
                    $c.tms.setSelectData(result.body, sbx_inqdisclsAnsTpCd, "cdValNm", "cdVal", "INQDISCLS_ANS_TP_CD", "cdEngNm");
                    // 서식작성방식 구분코드
                    $c.tms.setSelectData(result.body, sbx_formWrtMethdTpCd, "cdValNm", "cdVal", "FORM_WRT_METHD_TP_CD", "cdEngNm");                    
                    // 서식별 사용자 구분코드
                    $c.tms.setSelectData(result.body, sbx_byformUsrTpCd, "cdValNm", "cdVal", "BYFORM_USR_TP_CD", "cdEngNm");

                    setTimeout(scwin.changeRsnTpInfo(), 100);
                } else {
                    $c.win.alert(result.message);
                }
            };

            scwin.sbm_detail_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {                                        
                    // 이전 버전 자동 셋팅
                    dma_save.set("preFormVer", dma_save.get("formVer"));

                    // 영문서식 코드
                    if (dma_save.get("engFormYn") === "Y") {
                        ibx_engFormCd.setReadOnly(false);
                        ibx_engFormVer.setReadOnly(false);
                        ibx_formEngNm.setReadOnly(false);
                    } else {
                        ibx_engFormCd.setReadOnly(true);
                        ibx_engFormVer.setReadOnly(true);
                        ibx_formEngNm.setReadOnly(true);

                        ibx_engFormCd.setValue("");
                        ibx_engFormVer.setValue("");
                        ibx_formEngNm.setValue("");
                    }

                    let display_ = "";
                    let totYn_ = "";
                    // 서식첨부 구분 타이틀
                    if (dma_save.get("wrtrptMaindocTpCd") === "1") {                                               
                        display_ = "display:block";
                        totYn_ = "Y";                        
                    } else {                      
                        grp_info1.setStyle("display", "none");
                        grp_info4.setStyle("display", "none");

                        display_ = "display:none";
                        totYn_ = "N";
                    }

                    const formUpclssCd = dma_save.get("formUpclssCd");
                    const rsnClssCd = dma_save.get("rsnClssCd");
                    if ((formUpclssCd === "01" && rsnClssCd === "040") ||
                        (formUpclssCd === "01" && rsnClssCd === "041") ||
                        (formUpclssCd === "09" && rsnClssCd === "006") ||
                        (formUpclssCd === "09" && rsnClssCd === "009")) {                        
                        if (dma_save.get("inqdisclsTpCd") !== "A") {                                                        
                            grp_info3.setStyle("display", "none");
                        }
                    } else {
                        grp_info2.setStyle("display", "none");
                        grp_info3.setStyle("display", "none");
                    }

                    // 아코디언 처리
                    scwin.fnAccrodianProc(display_);
                    // 리스트 조회
                    scwin.fnSubList(totYn_);
                } else {
                    $c.win.alert(result.message);
                }
            };

            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    const obj = result.body;

                    // 서식양식정보 조회                
                    if (dlt_list1.getRowCount() > 0) {
                        ibx_roleId.setValue(dlt_list1.getCellData(0, "roleId"));
                        ibx_roleNmKoDspl.setValue(dlt_list1.getCellData(0, "roleNmKoDspl"));
                    }                                                          
                }
            };

            scwin.sbm_save_submitdone = async function (e) {

                const result = e.responseJSON;
                if (result.success) {
                    await $c.win.alert("저장 되었습니다.");
                    scwin.fnMove();
                } else {
                    $c.win.alert(result.message);
                }
            };

            scwin.fnMove = function () {

                let params = {};
                if (scwin.storageId !== "") {
                    params.storageId = scwin.storageId;
                }
                const url_ = "/ui/TMS/ULDTMS03010.xml";
                $c.win.moveUrl(url_, params);
            };

// 대분류, 시장구분 변경에 따른 사유, 유형정보 변경
            scwin.changeRsnTpInfo = function () {

                // WebSquere Map에 적용되는 갭이 존재하여
                // ref에 연결된 객체가 아닌 직접 컴퍼넌트에서 가져와 처리
                const params = {};
                params.formUpclssCd = sbx_formUpclssCd.getValue();
                params.ldMktTpCd = sbx_ldMktTpCd.getValue();
                // 기존에 목록을 사용해서 조회 하기 때문에 페이지 정보 추가
                params.page = "1";
                params.size = "100";

                // 사유 분류 정보 조회
                $c.sbm.execute(sbm_rsnclss, params);
            }

            scwin.sbm_rsnclss_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // 초기화
                    sbx_rsnClssCd.removeAll();
                    // select box 자동 생성
                    $c.tms.setSelectData(result.body.content, sbx_rsnClssCd, "disclsRsnClssNm", "rsnClssCd");
                    scwin.chageInqdisclsInfo1();
                    // 선택 버튼 추가 (공백이라도 값이 있어야 setValue나 setSelectedIndex가 정상 작동)
                    sbx_rsnClssCd.addItem(" ", "선택", "0");
                    sbx_rsnClssCd.setValue(" "); 

                } else {
                    $c.win.alert(result.message);
                }
            };

// 사유분류 변경에 따른 조회 공시 정보 변경
            scwin.chageInqdisclsInfo1 = function (e) {

                const formUpclssCd = sbx_formUpclssCd.getValue();
                const rsnClssCd = sbx_rsnClssCd.getValue();

                if ((formUpclssCd === "01" && rsnClssCd === "040") ||
                    (formUpclssCd === "01" && rsnClssCd === "041") ||
                    (formUpclssCd === "09" && rsnClssCd === "006") ||
                    (formUpclssCd === "09" && rsnClssCd === "009")) {
                   grp_info2.setStyle("display", "table-row");
                   scwin.chageInqdisclsInfo2();
                } else {
                   grp_info2.setStyle("display", "none");
                   grp_info3.setStyle("display", "none");
                }                               
            };

// 서식첨부구분
            scwin.chageWrtrptMainDocInfo = function () {

                let selectedIndex = sbx_listFormYn.getSelectedIndex();
                // 아코디언 제어 변수
                let display_ = "";                
                if (sbx_wrtrptMaindocTpCd.getValue() === "1") {                                                                   
                    grp_info1.setStyle("display", "table-row");
                    grp_info4.setStyle("display", "table-row");

                    sbx_formUpclssCd.setMandatory(true);
                    sbx_listFormYn.deleteItem(0, true);
                    sbx_listFormYn.addItem("Y", "상장", 0, true);
                    ibx_title.setValue("상장신청서구분");

                    display_ = "display:block";
                } else {                    
                    grp_info1.setStyle("display", "none");
                    grp_info4.setStyle("display", "none");

                    sbx_formUpclssCd.setMandatory(false);
                    sbx_listFormYn.deleteItem(0, true);
                    sbx_listFormYn.addItem("Y", "비공시", 0, true);                    
                    ibx_title.setValue("공시비공시구분");

                    display_ = "display:none";
                }                

                // 아코디언 숨김 처리
                scwin.fnAccrodianProc(display_);

                // 첫번째 item을 선택하고 있을때 처리
                if (selectedIndex === 0) {
                    sbx_listFormYn.setSelectedIndex(1);
                    sbx_listFormYn.setSelectedIndex(selectedIndex);
                }
                // 이쪽에서 다시 한번 조회 공시구분등 체크
                scwin.chageInqdisclsInfo1();                                
            };

// 조회 공시 구분에 따른 정보 변경
            scwin.chageInqdisclsInfo2 = function (e) {

                if (sbx_inqdisclsTpCd.getValue() === "A") {
                   grp_info3.setStyle("display", "table-row");
                } else {
                   grp_info3.setStyle("display", "none");
                }
            };

            scwin.fnSubList = function (totalYn) {

                // 상세 조회 처리
                const params = {};
                const data = dma_save.getJSON();

                params.formCd = dma_save.get("formCd");
                params.formVer = dma_save.get("formVer");
                params.totalYn = totalYn;
                params.listType = "";                

                $c.sbm.execute(sbm_list, params);                
            };

// 아코디언 처리
            scwin.fnAccrodianProc = function (display_) {

                const obj_ = acd_contents;
                if (obj_ !== null && obj_.panelInfoArr !== null && obj_.panelInfoArr.length >= 6) {
                    document.getElementById(obj_.panelInfoArr[3].id).style = display_;                    
                    document.getElementById(obj_.panelInfoArr[4].id).style = display_;
                    document.getElementById(obj_.panelInfoArr[5].id).style = display_;
                }
            };

            scwin.clear = function () {

                dma_save.setJSON({});
                dlt_list1.setJSON({});
                dlt_list2.setJSON({});
                dlt_list3.setJSON({});
                dlt_list4.setJSON({});
                dlt_list5.setJSON({});
                dlt_list6.setJSON({});
                dlt_list7.setJSON({});
                dlt_list8.setJSON({});

                ibx_oldFormCd.setValue("");
                ibx_roleId.setValue("");
                ibx_roleNmKoDspl.setValue("");
                sbx_engFormYn.setValue("Y");
                ibx_engFormCd.setReadOnly(false);
                ibx_engFormVer.setReadOnly(false);
                ibx_formEngNm.setReadOnly(false);

                scwin.fnAccrodianProc("display:block");
            }
